SELECT TABLE01.PORTFOLIO_ID portfolioId, TABLE01.SEC_ACCT_ID secAcctId, TABLE01.FINPROD_ID finProdId, TABLE01.BRANCH branch, IFNULL(TABLE02.AMOUNT,0) * 100 posStrdPrinAmt, IFNULL(TABLE01.AMOUNT,0) * 100 pledStrdPrinAmt, FIN_PRODUCT.TRADE_MARKET tradePlace, ETR_ENTRUST_PLEDGE.SCALE scale, FIN_PRODUCT.MDATE mdate, FIN_PRODUCT.REGIST_ORG registOrg, IFNULL(FIN_PRODUCT.FINPROD_ABBR,FIN_PRODUCT.FINPROD_NAME) finProdName, MST_BOND_VALUATION_INFO.LAST_PERIOD lastPeriod, FIN_PRODUCT.FINPROD_MARKET_ID finprodMarketId
FROM ETR_ENTRUST_PLEDGE LEFT JOIN ( SELECT TEMP.PORTFOLIO_ID, TEMP.SEC_ACCT_ID, TEMP.FINPROD_ID, TEMP.BRANCH, SUM(TEMP.AMOUNT) AMOUNT FROM ( SELECT PTL_SEC_POSITION.PORTFOLIO_ID, PTL_SEC_POSITION.SEC_ACCT_ID, PTL_SEC_POSITION.FINPROD_ID, PTL_SEC_POSITION.BRANCH, CASE WHEN PTL_SEC_POSITION.HODING_TYPE IN (#{POSITION_TYPE_03},#{POSITION_TYPE_05},#{POSITION_TYPE_08})then PTL_SEC_POSITION.AMOUNT ELSE -1 * PTL_SEC_POSITION.AMOUNT END as AMOUNT FROM PTL_SEC_POSITION WHERE 1=1 AND PTL_SEC_POSITION.CDATE = STR_TO_DATE(#{plateDate},'%Y-%m-%d')
AND PTL_SEC_POSITION.HODING_TYPE IN (#{POSITION_TYPE_03}, #{POSITION_TYPE_04},#{POSITION_TYPE_05}, #{POSITION_TYPE_06},#{POSITION_TYPE_08},#{POSITION_TYPE_11})
UNION ALL SELECT PTL_SEC_POSITION_FLOW.PORTFOLIO_ID, PTL_SEC_POSITION_FLOW.SEC_ACCT_ID, PTL_SEC_POSITION_FLOW.FINPROD_ID, PTL_SEC_POSITION_FLOW.BRANCH, CASE WHEN PTL_SEC_POSITION_FLOW.HODING_TYPE IN (#{POSITION_TYPE_01})then PTL_SEC_POSITION_FLOW.AMOUNT ELSE -1 * PTL_SEC_POSITION_FLOW.AMOUNT END as AMOUNT FROM PTL_SEC_POSITION_FLOW WHERE 1=1 AND PTL_SEC_POSITION_FLOW.CDATE = STR_TO_DATE(#{plateDate},'%Y-%m-%d')
AND PTL_SEC_POSITION_FLOW.HODING_TYPE IN (#{POSITION_TYPE_01}, #{POSITION_TYPE_12}) ) TEMP GROUP BY TEMP.PORTFOLIO_ID, TEMP.SEC_ACCT_ID, TEMP.FINPROD_ID, TEMP.PORTFOLIO_ID, TEMP.BRANCH HAVING SUM(TEMP.AMOUNT) > 0 )TABLE01 ON ETR_ENTRUST_PLEDGE.PORTFOLIO_ID = TABLE01.PORTFOLIO_ID AND ETR_ENTRUST_PLEDGE.FINPROD_ID = TABLE01.FINPROD_ID AND ETR_ENTRUST_PLEDGE.BRANCH = TABLE01.BRANCH AND ETR_ENTRUST_PLEDGE.SEC_ACCT_ID = TABLE01.SEC_ACCT_ID LEFT JOIN ( SELECT PTL_SEC_POSITION.PORTFOLIO_ID, PTL_SEC_POSITION.SEC_ACCT_ID, PTL_SEC_POSITION.FINPROD_ID, PTL_SEC_POSITION.BRANCH, SUM( CASE WHEN PTL_SEC_POSITION.HODING_TYPE IN (#{POSITION_TYPE_03},#{POSITION_TYPE_05})then PTL_SEC_POSITION.AMOUNT ELSE -1 * PTL_SEC_POSITION.AMOUNT END) as AMOUNT FROM PTL_SEC_POSITION WHERE 1=1 AND PTL_SEC_POSITION.CDATE = STR_TO_DATE(#{plateDate},'%Y-%m-%d')
AND PTL_SEC_POSITION.HODING_TYPE IN (#{POSITION_TYPE_03},#{POSITION_TYPE_05}, #{POSITION_TYPE_06},#{POSITION_TYPE_11}) GROUP BY PTL_SEC_POSITION.PORTFOLIO_ID, PTL_SEC_POSITION.SEC_ACCT_ID, PTL_SEC_POSITION.FINPROD_ID, PTL_SEC_POSITION.PORTFOLIO_ID, PTL_SEC_POSITION.BRANCH )TABLE02 ON ETR_ENTRUST_PLEDGE.PORTFOLIO_ID = TABLE02.PORTFOLIO_ID AND ETR_ENTRUST_PLEDGE.FINPROD_ID = TABLE02.FINPROD_ID AND ETR_ENTRUST_PLEDGE.BRANCH = TABLE02.BRANCH AND ETR_ENTRUST_PLEDGE.SEC_ACCT_ID = TABLE02.SEC_ACCT_ID INNER JOIN FIN_PRODUCT ON FIN_PRODUCT.FINPROD_ID = TABLE01.FINPROD_ID
AND FIN_PRODUCT.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F01}
LEFT JOIN ( SELECT T2.SEC_ID, T2.LAST_PERIOD FROM ( SELECT tmp1.SEC_ID, tmp1.value_source, MAX(tmp1.value_date) AS value_date FROM MST_BOND_VALUATION_INFO tmp1 LEFT JOIN FIN_PRODUCT tmp2 ON tmp1.sec_id = tmp2.finprod_market_id WHERE 1 = 1 AND tmp1.value_date <= STR_TO_DATE(#{plateDate},'%Y-%m-%d') AND tmp1.value_source = (CASE WHEN tmp2.trade_market IN (#{TRADEPLACE03},#{TRADEPLACE04}) THEN 'CSD' ELSE 'CBC' END) GROUP BY tmp1.sec_id, tmp1.value_source ) T1 LEFT JOIN MST_BOND_VALUATION_INFO T2 ON T1.SEC_ID = T2.SEC_ID AND T1.value_source = T2.value_source AND T1.VALUE_DATE = T2.VALUE_DATE ) MST_BOND_VALUATION_INFO ON FIN_PRODUCT.FINPROD_MARKET_ID = MST_BOND_VALUATION_INFO.SEC_ID
WHERE 1=1
AND FIN_PRODUCT.TRADE_MARKET IN (#{TRADEPLACE01},#{TRADEPLACE03},#{TRADEPLACE04})
AND (ETR_ENTRUST_PLEDGE.PORTFOLIO_ID in
null) or ETR_ENTRUST_PLEDGE.PORTFOLIO_ID in (
#{item}
)
AND FIN_PRODUCT.TRADE_MARKET in
#{item}
AND (ETR_ENTRUST_PLEDGE.SEC_ACCT_ID in
null) or ETR_ENTRUST_PLEDGE.SEC_ACCT_ID in (
#{item}
)

SELECT TABLE01.PORTFOLIO_ID portfolioId, TABLE01.SEC_ACCT_ID secAcctId, TABLE01.FINPROD_ID finProdId, TABLE01.BRANCH branch, IFNULL(TABLE01.AMOUNT,0) * 100 pledStrdPrinAmt, IFNULL(TABLE02.AMOUNT,0) * 100 posStrdPrinAmt, FIN_PRODUCT.TRADE_MARKET tradePlace, FIN_PRODUCT.MDATE mdate, MST_BOND_VALUATION_INFO.LAST_PERIOD lastPeriod, IFNULL(fscr.SCALE, 1)*100 scale, FIN_PRODUCT.FINPROD_MARKET_ID finprodMarketId FROM ( SELECT TEMP.PORTFOLIO_ID, TEMP.SEC_ACCT_ID, TEMP.FINPROD_ID, TEMP.BRANCH, SUM(TEMP.AMOUNT) AMOUNT FROM ( SELECT PTL_SEC_POSITION.PORTFOLIO_ID, PTL_SEC_POSITION.SEC_ACCT_ID, PTL_SEC_POSITION.FINPROD_ID, PTL_SEC_POSITION.BRANCH, CASE WHEN PTL_SEC_POSITION.HODING_TYPE IN (#{POSITION_TYPE_03},#{POSITION_TYPE_05},#{POSITION_TYPE_08})then PTL_SEC_POSITION.AMOUNT ELSE -1 * PTL_SEC_POSITION.AMOUNT END as AMOUNT FROM PTL_SEC_POSITION WHERE 1=1 AND PTL_SEC_POSITION.CDATE = STR_TO_DATE(#{plateDate},'%Y-%m-%d')
AND PTL_SEC_POSITION.HODING_TYPE IN (#{POSITION_TYPE_03}, #{POSITION_TYPE_04},#{POSITION_TYPE_05}, #{POSITION_TYPE_06},#{POSITION_TYPE_08},#{POSITION_TYPE_11})
UNION ALL SELECT PTL_SEC_POSITION_FLOW.PORTFOLIO_ID, PTL_SEC_POSITION_FLOW.SEC_ACCT_ID, PTL_SEC_POSITION_FLOW.FINPROD_ID, PTL_SEC_POSITION_FLOW.BRANCH, CASE WHEN PTL_SEC_POSITION_FLOW.HODING_TYPE IN (#{POSITION_TYPE_01})then PTL_SEC_POSITION_FLOW.AMOUNT ELSE -1 * PTL_SEC_POSITION_FLOW.AMOUNT END as AMOUNT FROM PTL_SEC_POSITION_FLOW WHERE 1=1 AND PTL_SEC_POSITION_FLOW.CDATE = STR_TO_DATE(#{plateDate},'%Y-%m-%d')
AND PTL_SEC_POSITION_FLOW.HODING_TYPE IN (#{POSITION_TYPE_01}, #{POSITION_TYPE_12}) ) TEMP LEFT JOIN PTL_PORTFOLIO_AUTHORITY on TEMP.PORTFOLIO_ID = PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID WHERE 1=1 AND PTL_PORTFOLIO_AUTHORITY.USER_ID = #{userId} GROUP BY TEMP.PORTFOLIO_ID, TEMP.SEC_ACCT_ID, TEMP.FINPROD_ID, TEMP.PORTFOLIO_ID, TEMP.BRANCH HAVING SUM(TEMP.AMOUNT) > 0 )TABLE01 LEFT JOIN ( SELECT PTL_SEC_POSITION.PORTFOLIO_ID, PTL_SEC_POSITION.SEC_ACCT_ID, PTL_SEC_POSITION.FINPROD_ID, PTL_SEC_POSITION.BRANCH, SUM( CASE WHEN PTL_SEC_POSITION.HODING_TYPE IN (#{POSITION_TYPE_03},#{POSITION_TYPE_05})then PTL_SEC_POSITION.AMOUNT ELSE -1 * PTL_SEC_POSITION.AMOUNT END) as AMOUNT FROM PTL_SEC_POSITION WHERE 1=1 AND PTL_SEC_POSITION.CDATE = STR_TO_DATE(#{plateDate},'%Y-%m-%d')
AND PTL_SEC_POSITION.HODING_TYPE IN (#{POSITION_TYPE_03},#{POSITION_TYPE_05}, #{POSITION_TYPE_06},#{POSITION_TYPE_11}) GROUP BY PTL_SEC_POSITION.PORTFOLIO_ID, PTL_SEC_POSITION.SEC_ACCT_ID, PTL_SEC_POSITION.FINPROD_ID, PTL_SEC_POSITION.PORTFOLIO_ID, PTL_SEC_POSITION.BRANCH )TABLE02 ON TABLE01.PORTFOLIO_ID = TABLE02.PORTFOLIO_ID AND TABLE01.SEC_ACCT_ID = TABLE02.SEC_ACCT_ID AND TABLE01.FINPROD_ID = TABLE02.FINPROD_ID AND TABLE01.BRANCH = TABLE02.BRANCH INNER JOIN FIN_PRODUCT ON FIN_PRODUCT.FINPROD_ID = TABLE01.FINPROD_ID LEFT JOIN ( SELECT T2.SEC_ID, T2.LAST_PERIOD FROM ( SELECT tmp1.SEC_ID, tmp1.value_source, MAX(tmp1.value_date) AS value_date FROM MST_BOND_VALUATION_INFO tmp1 LEFT JOIN FIN_PRODUCT tmp2 ON tmp1.sec_id = tmp2.finprod_market_id WHERE 1 = 1 AND tmp1.value_date <= STR_TO_DATE(#{plateDate},'%Y-%m-%d') AND tmp1.value_source = (CASE WHEN tmp2.trade_market IN (#{TRADEPLACE03},#{TRADEPLACE04}) THEN 'CSD' ELSE 'CBC' END) GROUP BY tmp1.sec_id, tmp1.value_source ) T1 LEFT JOIN MST_BOND_VALUATION_INFO T2 ON T1.SEC_ID = T2.SEC_ID AND T1.value_source = T2.value_source AND T1.VALUE_DATE = T2.VALUE_DATE ) MST_BOND_VALUATION_INFO ON FIN_PRODUCT.FINPROD_MARKET_ID = MST_BOND_VALUATION_INFO.SEC_ID LEFT JOIN FIN_STDSEC_CONVERSE_RADIO fscr ON fscr.FINPROD_ID = TABLE01.FINPROD_ID AND fscr.BRANCH = TABLE01.BRANCH AND fscr.VDATE <= STR_TO_DATE(#{plateDate}, '%Y-%m-%d') AND NOT EXISTS ( SELECT * FROM FIN_STDSEC_CONVERSE_RADIO fscrInner WHERE fscrInner.FINPROD_ID = fscr.FINPROD_ID AND fscrInner.BRANCH = fscr.BRANCH AND fscrInner.VDATE <= STR_TO_DATE(#{plateDate}, '%Y-%m-%d') AND fscrInner.VDATE > fscr.VDATE ) WHERE 1=1 AND FIN_PRODUCT.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F01}
AND FIN_PRODUCT.TRADE_MARKET IN (#{TRADEPLACE01},#{TRADEPLACE03},#{TRADEPLACE04})
AND (TABLE01.PORTFOLIO_ID in
null) or TABLE01.PORTFOLIO_ID in (
#{item}
)
AND FIN_PRODUCT.TRADE_MARKET in
#{item}
AND (TABLE01.SEC_ACCT_ID in
null) or TABLE01.SEC_ACCT_ID in (
#{item}
)

SELECT TABLE01.PORTFOLIO_ID portfolioId, TABLE01.SEC_ACCT_ID secAcctId, TABLE01.FINPROD_ID finProdId, TABLE01.BRANCH branch, IFNULL(TABLE01.AMOUNT,0) * 100 pledStrdPrinAmt, FIN_PRODUCT.TRADE_MARKET tradePlace, ETR_ENTRUST_PLEDGE.SCALE scale
FROM ETR_ENTRUST_PLEDGE LEFT JOIN PTL_PORTFOLIO_AUTHORITY on ETR_ENTRUST_PLEDGE.PORTFOLIO_ID = PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID INNER JOIN ( SELECT TEMP.PORTFOLIO_ID, TEMP.SEC_ACCT_ID, TEMP.FINPROD_ID, TEMP.BRANCH, SUM(TEMP.AMOUNT) AMOUNT FROM ( SELECT PTL_SEC_POSITION.PORTFOLIO_ID, PTL_SEC_POSITION.SEC_ACCT_ID, PTL_SEC_POSITION.FINPROD_ID, PTL_SEC_POSITION.BRANCH, CASE WHEN PTL_SEC_POSITION.HODING_TYPE IN (#{POSITION_TYPE_03},#{POSITION_TYPE_05},#{POSITION_TYPE_08})then PTL_SEC_POSITION.AMOUNT ELSE -1 * PTL_SEC_POSITION.AMOUNT END as AMOUNT FROM PTL_SEC_POSITION WHERE 1=1 AND PTL_SEC_POSITION.CDATE = STR_TO_DATE(#{plateDate},'%Y-%m-%d')
AND PTL_SEC_POSITION.HODING_TYPE IN (#{POSITION_TYPE_03}, #{POSITION_TYPE_04},#{POSITION_TYPE_05}, #{POSITION_TYPE_06},#{POSITION_TYPE_08},#{POSITION_TYPE_11})
UNION ALL SELECT PTL_SEC_POSITION_FLOW.PORTFOLIO_ID, PTL_SEC_POSITION_FLOW.SEC_ACCT_ID, PTL_SEC_POSITION_FLOW.FINPROD_ID, PTL_SEC_POSITION_FLOW.BRANCH, CASE WHEN PTL_SEC_POSITION_FLOW.HODING_TYPE IN (#{POSITION_TYPE_01})then PTL_SEC_POSITION_FLOW.AMOUNT ELSE -1 * PTL_SEC_POSITION_FLOW.AMOUNT END as AMOUNT FROM PTL_SEC_POSITION_FLOW WHERE 1=1 AND PTL_SEC_POSITION_FLOW.CDATE = STR_TO_DATE(#{plateDate},'%Y-%m-%d')
AND PTL_SEC_POSITION_FLOW.HODING_TYPE IN (#{POSITION_TYPE_01}, #{POSITION_TYPE_12}) ) TEMP GROUP BY TEMP.PORTFOLIO_ID, TEMP.SEC_ACCT_ID, TEMP.FINPROD_ID, TEMP.PORTFOLIO_ID, TEMP.BRANCH HAVING SUM(TEMP.AMOUNT) > 0 )TABLE01 ON ETR_ENTRUST_PLEDGE.PORTFOLIO_ID = TABLE01.PORTFOLIO_ID AND ETR_ENTRUST_PLEDGE.FINPROD_ID = TABLE01.FINPROD_ID AND ETR_ENTRUST_PLEDGE.BRANCH = TABLE01.BRANCH AND ETR_ENTRUST_PLEDGE.SEC_ACCT_ID = TABLE01.SEC_ACCT_ID INNER JOIN FIN_PRODUCT ON FIN_PRODUCT.FINPROD_ID = TABLE01.FINPROD_ID
AND FIN_PRODUCT.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F01}
WHERE 1=1 AND PTL_PORTFOLIO_AUTHORITY.USER_ID = #{userId}
AND FIN_PRODUCT.TRADE_MARKET IN (#{TRADEPLACE01},#{TRADEPLACE03},#{TRADEPLACE04})
AND (TABLE01.PORTFOLIO_ID in
null) or TABLE01.PORTFOLIO_ID in (
